import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.Timer;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class MonitoredThreadPoolService {
    private final ThreadPoolExecutor executor;
    private final Timer executionTimer;

    public MonitoredThreadPoolService(ThreadPoolExecutor executor, MeterRegistry registry) {
        this.executor = executor;
        this.executionTimer = Timer.builder("service.task.execution")
            .description("Execution time of core business tasks")
            .register(registry);

        registry.gauge("service.threadpool.active", executor, ThreadPoolExecutor::getActiveCount);
        registry.gauge("service.threadpool.queue.size", executor, e -> e.getQueue().size());
    }

    public void submitTask(Runnable task) {
        long startTime = System.nanoTime();
        executor.submit(() -> {
            try {
                task.run();
            } finally {
                executionTimer.record(System.nanoTime() - startTime, TimeUnit.NANOS);
            }
        });
    }
}
